/**
 * The preview's fourth toil project, `sample-team`: a web shop's two squads,
 * six sprints and three releases, generated by toil's own `sampleTeam()`
 * (src/core/sample/), which is a pure function of one day. The data here is
 * that function's, answered back the way each command prints it: the Jira
 * search with every issue's history inline, the GitHub pull request list and
 * a get for each, and a CODEOWNERS file, which the generator has no use for
 * and the reviewer suggestion does, so this file invents the smallest one that
 * names the sample's own logins. Nothing is typed twice; the headcount, the
 * sprint dates and the missing estimates are all downstream of one seed.
 * The seed is dated, as every record of a team of any size eventually is.
 */

import { sampleTeam } from '../../../src/core/sample/team.ts';
import { PEOPLE } from '../../../src/core/sample/people.ts';

import { SAMPLE_AS_OF } from './now.ts';

/** The moment the sample data was read: day seven of Sprint 42, which is also the sample team's seventh working day of ten. */
export { SAMPLE_AS_OF };

export const SAMPLE_TEAM = sampleTeam(SAMPLE_AS_OF);

/** The toil project file, as `~/.toil/projects/sample-team.json` would hold it. */
export const SAMPLE_PROJECT_FILE = { ...SAMPLE_TEAM.toilProject, description: 'A whole sample team: two squads, six sprints, three releases and an AI agent. Nothing to set up.' };

/** `jira issue search --changelog`'s data: every issue, its history inline. */
export const SAMPLE_JIRA_SEARCH = SAMPLE_TEAM.jira;

/** The sample's repository, as the toil project names it. */
export const SAMPLE_GITHUB = { owner: 'imagile', repo: 'shop' };

/** The keys `pr get --include …` returns beyond what `pr list` lists. */
const GET_ONLY = ['merged', 'mergeable', 'mergeable_state', 'comments', 'review_comments', 'commits', 'additions', 'deletions', 'changed_files', 'included'];

/** `github pr list --state all`'s data: each pull request without what only a get reads. */
export const SAMPLE_PR_LIST = SAMPLE_TEAM.prs.map((pr) => Object.fromEntries(Object.entries(pr).filter(([k]) => !GET_ONLY.includes(k))));

/** `github pr get <n> --include reviews,checks,commits,files`, by number. */
export const SAMPLE_PR_GETS: Record<number, unknown> = Object.fromEntries(SAMPLE_TEAM.prs.map((pr) => [pr.number as number, pr]));

const login = (key: string) => `@${PEOPLE.find((p) => p.key === key)!.github}`;
const CODEOWNERS_TEXT = ['# Who reviews what', `* ${login('ml')}`, `src/checkout/ ${login('ac')} ${login('js')}`, `src/orders/ ${login('kn')} ${login('rp')}`, `jobs/ ${login('sg')} ${login('do')}`, `package.json ${login('tn')}`, ''].join('\n');

/** `github repo file .github/CODEOWNERS`'s data. */
export const SAMPLE_CODEOWNERS = {
  type: 'file',
  encoding: 'base64',
  size: CODEOWNERS_TEXT.length,
  name: 'CODEOWNERS',
  path: '.github/CODEOWNERS',
  // btoa, not Buffer: the preview runs this fixture in a browser.
  content: btoa(CODEOWNERS_TEXT),
  sha: 'abc12345abc12345abc12345abc12345abc12345',
  html_url: `https://github.imagile.dev/${SAMPLE_GITHUB.owner}/${SAMPLE_GITHUB.repo}/blob/main/.github/CODEOWNERS`,
  text: CODEOWNERS_TEXT,
};
